#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeViewport: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Viewport

    public static func lift(_ handle: UInt64) throws -> Viewport {
        return Viewport(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Viewport) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Viewport {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Viewport, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
