/**
 * Tasten für den Editor.
 */

public enum KeyInput: Equatable, Hashable {
    
    case escape
    case enter
    case delete
    case tab
    /**
     * Pfeiltaste, `large` mit ⇧.
     */
    case arrow(dx: Int8, dy: Int8, large: Bool
    )
    case character(text: String
    )





}

#if compiler(>=6)
extension KeyInput: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeKeyInput: FfiConverterRustBuffer {
    typealias SwiftType = KeyInput

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> KeyInput {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .escape
        
        case 2: return .enter
        
        case 3: return .delete
        
        case 4: return .tab
        
        case 5: return .arrow(dx: try FfiConverterInt8.read(from: &buf), dy: try FfiConverterInt8.read(from: &buf), large: try FfiConverterBool.read(from: &buf)
        )
        
        case 6: return .character(text: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: KeyInput, into buf: inout [UInt8]) {
        switch value {
        
        
        case .escape:
            writeInt(&buf, Int32(1))
        
        
        case .enter:
            writeInt(&buf, Int32(2))
        
        
        case .delete:
            writeInt(&buf, Int32(3))
        
        
        case .tab:
            writeInt(&buf, Int32(4))
        
        
        case let .arrow(dx,dy,large):
            writeInt(&buf, Int32(5))
            FfiConverterInt8.write(dx, into: &buf)
            FfiConverterInt8.write(dy, into: &buf)
            FfiConverterBool.write(large, into: &buf)
            
        
        case let .character(text):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(text, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeKeyInput_lift(_ buf: RustBuffer) throws -> KeyInput {
    return try FfiConverterTypeKeyInput.lift(buf)
}

